    div = next(r for r,row in enumerate(grid) if all(v==2 for v in row))
    for r in range(div):
        for c in range(w):
            if grid[r][c] == 4:
                # first row immediately below the divider is offset 1;
                # subsequent rows alternate outward offsets 1,3,5,...
                for k in range(h-div):
                    rr=div+k
                    d=2*k+1
                    for cc in (c-d,c+d):
                        if 0<=cc<w: out[rr][cc]=4
    return out

