def transform(grid):
    # A 4 marker generates the demonstrated five-cell diagonal pattern:
    # two cells one row above at ±2 columns, two same-row at ±1,
    # and one cell one row below at the same column.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 4:
                pattern = [(-1,-2), (-1,2), (0,-1), (0,1), (1,0)]
                for dr, dc in pattern:
                    rr, cc = r+dr, c+dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 4
    return out

