def transform(grid):
    # Each 4 marker stamps its five-cell motif on the same side of the
    # divider as the source: (r-1,c±2), (r,c±1), (r+1,c).
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    div = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), h)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                continue
            # The demo shows the two outer diagonal tips on row above,
            # lateral cells on the source row, then a center cell below.
            for dr, dc in [(-1,-2),(-1,2),(0,-1),(0,1),(1,0)]:
                rr, cc = r+dr, c+dc
                if 0 <= rr < h and 0 <= cc < w and (rr < div if r < div else rr > div):
                    if (rr, cc) != (r, c):
                        out[rr][cc] = 4
    return out

