def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The examples show 4s reflecting along diagonals around the 2 separator.
    # Upper-panel markers continue down-right and lower-panel markers continue
    # up-left; stop at the separator, edge, or another existing marker.
    div = next((r for r,row in enumerate(grid) if all(v == 2 for v in row)), h)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                continue
            if r < div:
                for d in range(1, min(div-r, w-c)):
                    rr, cc = r+d, c+d
                    if grid[rr][cc] == 4:
                        break
                    out[rr][cc] = 4
            elif r > div:
                for d in range(1, min(r-div, c+1)):
                    rr, cc = r-d, c-d
                    if grid[rr][cc] == 4:
                        break
                    out[rr][cc] = 4
    return out

