def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    div = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    if div is None:
        return [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2
            elif grid[r][c] == 4:
                # Near the divider, the marker leaves the demonstrated local
                # five-cell trace; otherwise it advances one row downward.
                if r < div and div-r == 2:
                    for dr, dc in [(-1,-2),(-1,2),(0,-1),(0,1),(1,0)]:
                        rr, cc = r+dr, c+dc
                        if 0 <= rr < h and 0 <= cc < w and rr != div:
                            out[rr][cc] = 4
                else:
                    rr = min(r+1, h-1)
                    if rr != div:
                        out[rr][c] = 4
    return out
